import type { AuthUser } from './infrastructure/auth/better-auth';

/**
 * Worker bindings. `Cloudflare.Env` is generated by `wrangler types` (worker-configuration.d.ts)
 * from wrangler.jsonc — run `pnpm cf-typegen` after changing bindings.
 *
 * Secrets and optional vars that are not in every wrangler env are declared here so production
 * code can't forget them.
 */
export interface Env extends Omit<
  Cloudflare.Env,
  'DEV_AUTH' | 'BETTER_AUTH_SECRET' | 'EMAIL' | 'EMAIL_FROM'
> {
  /** Cloudflare Email Service binding — production only (wrangler.jsonc env.production). */
  EMAIL?: SendEmail;
  /** Local only (wrangler.jsonc top-level vars / .dev.vars). The Worker refuses to serve if set
   *  when ENVIRONMENT !== "local". */
  DEV_AUTH?: string;
  /** TEST-ONLY engine switch (`fake`). Refused unless ENVIRONMENT === "local". See composition.ts. */
  ENGINE?: string;
  /** Secret (wrangler secret put BETTER_AUTH_SECRET). Optional locally. */
  BETTER_AUTH_SECRET?: string;
  /** Public origin for auth (defaults to the request origin). */
  BETTER_AUTH_URL?: string;
  /** Comma-separated extra trusted origins (e.g. the Vite dev server). */
  AUTH_TRUSTED_ORIGINS?: string;
  /** Secret: Resend API key for sign-in emails (staging/production). */
  RESEND_API_KEY?: string;
  EMAIL_FROM?: string;
}

export interface AppVariables {
  requestId: string;
  /** Set by the requireUser middleware. */
  user: AuthUser | undefined;
}

/** Hono generic environment for the app. */
export interface AppEnv {
  Bindings: Env;
  Variables: AppVariables;
}
